{# An Yuan Motors | ERPNext Sales Invoice | ZATCA Phase 1 #}
{% set settings = frappe.db.get_value('ZATCA Phase 1 Business Settings', {'company': doc.company}, ['company', 'vat_registration_number', 'address', 'status', 'type_of_transaction'], as_dict=1) or {} %}
{% set seller_address = frappe.db.get_value('Address', settings.get('address'), ['address_line1', 'address_line2', 'city', 'state', 'pincode', 'country'], as_dict=1) if settings.get('address') else {} %}
{% set seller_address = seller_address or {} %}
{% set company_info = frappe.db.get_value('Company', doc.company, ['company_name', 'tax_id'], as_dict=1) or {} %}
{% set buyer = frappe.db.get_value('Customer', doc.customer, ['customer_name', 'tax_id', 'custom_vat_registration_number'], as_dict=1) or {} %}
{% set customer_vat = buyer.get('custom_vat_registration_number') or buyer.get('tax_id') or '' %}
{% set buyer_cr = frappe.db.get_value('Additional Buyer IDs', {'parent': doc.customer, 'type_name': 'Commercial Registration Number'}, 'value') or '' %}
{% set buyer_address_name = doc.customer_address or frappe.db.get_value('Dynamic Link', {'parenttype': 'Address', 'link_name': doc.customer, 'link_doctype': 'Customer'}, 'parent') %}
{% set buyer_address = frappe.db.get_value('Address', buyer_address_name, ['address_line1', 'address_line2', 'city', 'state', 'pincode', 'country'], as_dict=1) if buyer_address_name else {} %}
{% set buyer_address = buyer_address or {} %}
{% set transaction_type = settings.get('type_of_transaction') or 'Both' %}
{% set is_standard = (transaction_type == 'Standard Tax Invoice') or (transaction_type == 'Both' and customer_vat) %}
{% set seller_name = settings.get('company') or company_info.get('company_name') or doc.company %}
{% set seller_vat = settings.get('vat_registration_number') or company_info.get('tax_id') or '' %}
{% set ns = namespace(tax_total=0) %}
{% for tax in doc.taxes %}{% if tax.charge_type == 'On Net Total' and ('VAT' in (tax.description or '') or 'ضريبة' in (tax.description or '') or tax.rate == 15) %}{% set ns.tax_total = ns.tax_total + (tax.tax_amount or 0) %}{% endif %}{% endfor %}
{% set tax_amount = ns.tax_total if ns.tax_total else (doc.total_taxes_and_charges or 0) %}
{% set currency = doc.currency or 'SAR' %}
{% set grand = (doc.grand_total or 0) | abs %}
{% set net = (doc.net_total or 0) | abs %}
{% set tax = tax_amount | abs %}
{% set is_credit = doc.is_return %}
<style>
@page { size: A4; margin: 12mm 12mm 14mm; }
@media print { html,body { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; } .print-format { padding: 0 !important; margin: 0 !important; } .invoice-shell { box-shadow: none !important; } tr { page-break-inside: avoid; } .avoid-break { page-break-inside: avoid; } }
.print-format { padding: 0 !important; font-family: 'Arial', 'Noto Sans Arabic', 'Tahoma', sans-serif !important; color: #1e293b; font-size: 10px; }
.print-format .invoice-shell { font-family: 'Arial', 'Noto Sans Arabic', 'Tahoma', sans-serif; color:#1e293b; direction:rtl; line-height:1.55; }
.invoice-shell * { box-sizing:border-box; }
.invoice-shell .invoice-top { width:100%; border-collapse:collapse; border-bottom:3px solid #163b48; margin-bottom:12px; }
.invoice-shell .invoice-top td { border:0; vertical-align:middle; padding:0 0 10px; }
.invoice-shell .brand-ar { color:#123e4b; font-size:20px; font-weight:800; line-height:1.35; }
.invoice-shell .brand-en { color:#6a7e89; font-size:11px; font-weight:700; direction:ltr; text-align:right; }
.invoice-shell .tagline { color:#a78338; font-size:10px; font-weight:700; margin-top:2px; }
.invoice-shell .doc-type { display:inline-block; border:1px solid #ccad62; background:#fbf7ed; padding:7px 13px; color:#193f4a; text-align:center; min-width:164px; border-radius:4px; }
.invoice-shell .doc-type .ar { font-size:15px; font-weight:800; }
.invoice-shell .doc-type .en { font-size:10px; font-weight:700; letter-spacing:0.6px; }
.invoice-shell .meta { width:100%; border-collapse:separate; border-spacing:6px 0; margin:0 -6px 12px; }
.invoice-shell .meta td { border:1px solid #dce5e9; border-radius:5px; padding:7px 10px; background:#f5f8f9; width:25%; vertical-align:top; }
.invoice-shell .label { display:block; color:#71828b !important; background:none !important; font-size:9px; font-weight:600; margin:0; padding:0; white-space:normal; border:0; }
.invoice-shell .value { display:block; font-size:11px; color:#173c47; font-weight:700; margin-top:3px; overflow-wrap:anywhere; }
.invoice-shell .ltr { direction:ltr; unicode-bidi:embed; display:inline-block; }
.invoice-shell .info { width:100%; border-collapse:separate; border-spacing:8px 0; margin:0 -8px 12px; }
.invoice-shell .info td { border:1px solid #dce5e9; border-top:3px solid #1b5662; width:50%; padding:9px 11px; vertical-align:top; border-radius:5px; }
.invoice-shell .section-heading { color:#164653; font-size:12px; font-weight:800; margin-bottom:6px; }
.invoice-shell .mini-row { padding:3px 0; border-bottom:1px dotted #e6edf0; }
.invoice-shell .mini-row:last-child { border-bottom:0; }
.invoice-shell .mini-label { color:#74858c; font-weight:500; }
.invoice-shell .mini-value { color:#213c45; font-weight:700; }
.invoice-shell .items { border-collapse:collapse; width:100%; margin:3px 0 10px; table-layout:fixed; }
.invoice-shell .items thead th { background:#174b58 !important; color:#fff !important; border:1px solid #174b58; padding:8px 5px; text-align:center; font-weight:700; font-size:10px; }
.invoice-shell .items tbody td { border:1px solid #dce5e9; padding:8px 5px; vertical-align:top; font-size:10px; }
.invoice-shell .items tbody tr:nth-child(even) td { background:#f6f9fa; }
.invoice-shell .items .item-name { font-weight:700; color:#163d48; }
.invoice-shell .muted { color:#87949c; font-size:9px; }
.invoice-shell .num { direction:ltr; text-align:center; white-space:nowrap; font-variant-numeric:tabular-nums; }
.invoice-shell .totals-layout { width:100%; border-collapse:separate; border-spacing:10px 0; margin:0 -10px 6px; }
.invoice-shell .totals-layout td { vertical-align:top; border:0; }
.invoice-shell .qrbox { width:36%; text-align:center; border:1px solid #dbe5e7 !important; border-radius:5px; padding:9px !important; }
.invoice-shell .qrbox img { display:block; width:124px; height:124px; margin:0 auto 4px; object-fit:contain; }
.invoice-shell .summary-wrap { width:64%; }
.invoice-shell .summary { width:100%; border-collapse:collapse; }
.invoice-shell .summary td { border:0; border-bottom:1px solid #e7edef; padding:6px 9px; }
.invoice-shell .summary .money { direction:ltr; text-align:left; white-space:nowrap; font-weight:700; }
.invoice-shell .summary .grand-row td { background:#174b58 !important; color:#fff !important; font-size:13px; font-weight:800; border:0; padding:10px; }
.invoice-shell .bottomnote { margin-top:13px; border-top:1px solid #dbe5e9; padding-top:9px; color:#72828b; text-align:center; font-size:9px; }
.invoice-shell .status-note { background:#fff4e5; color:#875d14; padding:7px 10px; margin:8px 0; border:1px solid #e9d5a5; border-radius:4px; }
</style>
<div class="invoice-shell">
  {% if letter_head %}<div class="invoice-letterhead">{{ letter_head }}</div>{% endif %}
  <table class="invoice-top"><tr>
    <td style="width:64%; text-align:right;">
      <div class="brand-ar">{{ seller_name }}</div>
      <div class="brand-en">An Yuan Motors Co Company</div>
      <div class="tagline">مبيعات المركبات والشاحنات | Vehicle &amp; Truck Sales</div>
    </td>
    <td style="width:36%; text-align:left;">
      <div class="doc-type"><div class="ar">{% if is_credit %}إشعار دائن ضريبي{% elif doc.is_debit_note %}إشعار مدين ضريبي{% elif is_standard %}فاتورة ضريبية{% else %}فاتورة ضريبية مبسطة{% endif %}</div><div class="en">{% if is_credit %}TAX CREDIT NOTE{% elif doc.is_debit_note %}TAX DEBIT NOTE{% elif is_standard %}TAX INVOICE{% else %}SIMPLIFIED TAX INVOICE{% endif %}</div></div>
    </td>
  </tr></table>

  <table class="meta"><tr>
    <td><span class="label">رقم الفاتورة / Invoice No.</span><span class="value ltr">{{ doc.name }}</span></td>
    <td><span class="label">تاريخ الفاتورة / Issue Date</span><span class="value ltr">{{ doc.get_formatted('posting_date') }}</span></td>
    <td><span class="label">وقت الإصدار / Issue Time</span><span class="value ltr">{{ doc.posting_time or '—' }}</span></td>
    <td><span class="label">طريقة الدفع / Payment</span><span class="value">{% if doc.is_pos %}نقاط البيع / POS{% elif doc.get('mode_of_payment') %}{{ doc.mode_of_payment }}{% elif doc.get('payment_terms_template') %}{{ doc.payment_terms_template }}{% else %}—{% endif %}</span></td>
  </tr></table>

  <table class="info"><tr>
    <td>
      <div class="section-heading">بيانات البائع <span class="muted">/ Seller Details</span></div>
      <div class="mini-row"><span class="mini-label">الاسم / Name:</span> <span class="mini-value">{{ seller_name }}</span></div>
      <div class="mini-row"><span class="mini-label">الرقم الضريبي / VAT:</span> <span class="mini-value ltr">{{ seller_vat or '—' }}</span></div>
      <div class="mini-row"><span class="mini-label">العنوان / Address:</span> <span class="mini-value">{{ [seller_address.get('address_line1'), seller_address.get('address_line2'), seller_address.get('state'), seller_address.get('city'), seller_address.get('pincode')] | select | join('، ') or '—' }}</span></div>
      <div class="mini-row"><span class="mini-label">الدولة / Country:</span> <span class="mini-value">{{ seller_address.get('country') or 'Saudi Arabia' }}</span></div>
    </td>
    <td>
      <div class="section-heading">بيانات المشتري <span class="muted">/ Buyer Details</span></div>
      <div class="mini-row"><span class="mini-label">الاسم / Name:</span> <span class="mini-value">{{ buyer.get('customer_name') or doc.customer_name or doc.customer }}</span></div>
      <div class="mini-row"><span class="mini-label">الرقم الضريبي / VAT:</span> <span class="mini-value ltr">{{ customer_vat or '—' }}</span></div>
      <div class="mini-row"><span class="mini-label">السجل التجاري / CR:</span> <span class="mini-value ltr">{{ buyer_cr or '—' }}</span></div>
      <div class="mini-row"><span class="mini-label">العنوان / Address:</span> <span class="mini-value">{{ [buyer_address.get('address_line1'), buyer_address.get('address_line2'), buyer_address.get('state'), buyer_address.get('city'), buyer_address.get('pincode')] | select | join('، ') or '—' }}</span></div>
    </td>
  </tr></table>

  {% if is_standard and not customer_vat %}<div class="status-note">تنبيه: الفاتورة الضريبية القياسية تحتاج مراجعة الرقم الضريبي للمشتري إذا كان مسجلاً في ضريبة القيمة المضافة.</div>{% endif %}

  <table class="items">
    <thead><tr><th style="width:5%">#</th><th style="width:34%">الصنف / Item</th><th style="width:11%">الكمية<br>Qty</th><th style="width:16%">سعر الوحدة<br>Unit Price</th><th style="width:17%">قبل الضريبة<br>Net Amount</th><th style="width:17%">الإجمالي<br>Total</th></tr></thead>
    <tbody>
      {% for item in doc.items %}
      <tr>
        <td class="num">{{ item.idx }}</td>
        <td><div class="item-name">{{ item.item_name }}</div>{% if item.item_code != item.item_name %}<div class="muted ltr">{{ item.item_code }}</div>{% endif %}{% if item.description and item.description != item.item_name %}<div class="muted">{{ item.description | striptags }}</div>{% endif %}</td>
        <td class="num">{{ item.qty | abs }} {{ item.uom or '' }}</td>
        <td class="num">{{ frappe.utils.fmt_money(item.rate | abs, currency=currency) }}</td>
        <td class="num">{{ frappe.utils.fmt_money(item.net_amount | abs, currency=currency) }}</td>
        <td class="num">{{ frappe.utils.fmt_money(item.amount | abs, currency=currency) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <table class="totals-layout avoid-break"><tr>
    <td class="summary-wrap">
      <table class="summary">
        <tr><td>الإجمالي قبل الضريبة <span class="muted">/ Net Total</span></td><td class="money">{{ frappe.utils.fmt_money(net, currency=currency) }}</td></tr>
        <tr><td>الخصم <span class="muted">/ Discount</span></td><td class="money">{{ frappe.utils.fmt_money((doc.discount_amount or 0) | abs, currency=currency) }}</td></tr>
        <tr><td>الضريبة والرسوم <span class="muted">/ Taxes &amp; Charges</span></td><td class="money">{{ frappe.utils.fmt_money((doc.total_taxes_and_charges or 0) | abs, currency=currency) }}</td></tr>
        {% if (tax - (doc.total_taxes_and_charges or 0) | abs) | abs > 0.01 %}<tr><td>ضريبة القيمة المضافة <span class="muted">/ VAT (subset)</span></td><td class="money">{{ frappe.utils.fmt_money(tax, currency=currency) }}</td></tr>{% endif %}
        {% if doc.rounding_adjustment %}<tr><td>فروقات التقريب / Rounding</td><td class="money">{{ frappe.utils.fmt_money(doc.rounding_adjustment | abs, currency=currency) }}</td></tr>{% endif %}
        <tr class="grand-row"><td>الإجمالي شامل الضريبة / Grand Total</td><td class="money">{{ frappe.utils.fmt_money((doc.rounded_total if doc.rounded_total else doc.grand_total) | abs, currency=currency) }}</td></tr>
      </table>
    </td>
    <td class="qrbox">
      {% if settings.get('status') == 'Active' and doc.docstatus == 1 %}
        <img src="data:image/png;base64,{{ get_zatca_phase_1_qr_for_invoice(doc.name) }}" alt="ZATCA QR Code">
        <strong>رمز الاستجابة السريعة</strong><div class="muted">ZATCA VAT QR</div>
      {% else %}
        <div class="muted" style="padding:25px 0">يظهر رمز ZATCA بعد اعتماد الفاتورة وتفعيل الإعدادات</div>
      {% endif %}
    </td>
  </tr></table>

  {% if doc.remarks %}<div class="status-note">ملاحظات / Notes: {{ doc.remarks }}</div>{% endif %}
  <div class="bottomnote">فاتورة منشأة إلكترونياً من النظام | Electronically generated invoice<br>الرجاء التحقق من صحة البيانات والرمز الضريبي قبل اعتماد المستند</div>
</div>
